import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../providers/quiz_provider.dart';
import '../theme/app_theme.dart';
import '../widgets/primary_button.dart';
import 'home_screen.dart';
class BiodataScreen extends StatefulWidget { const BiodataScreen({super.key}); @override State<BiodataScreen> createState()=>_BiodataScreenState(); }
class _BiodataScreenState extends State<BiodataScreen>{final _formKey=GlobalKey<FormState>();final _name=TextEditingController();final _nim=TextEditingController();final _program=TextEditingController();
@override void dispose(){_name.dispose();_nim.dispose();_program.dispose();super.dispose();}
void _continue(){if(!_formKey.currentState!.validate())return;context.read<QuizProvider>().setProfile(name:_name.text,nim:_nim.text,program:_program.text);Navigator.of(context).pushReplacement(MaterialPageRoute(builder:(_)=>const HomeScreen()));}
@override Widget build(BuildContext context){final width=MediaQuery.sizeOf(context).width;final h=width>600?width*.2:24.0;return Scaffold(appBar:AppBar(title:const Text('Profil peserta',style:TextStyle(fontWeight:FontWeight.w900))),body:SafeArea(child:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:560),child:SingleChildScrollView(padding:EdgeInsets.fromLTRB(h,16,h,28),child:Form(key:_formKey,child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Center(child:Container(width:88,height:88,decoration:BoxDecoration(color:AppTheme.violet.withValues(alpha:.12),borderRadius:BorderRadius.circular(26)),child:const Icon(Icons.account_circle_rounded,color:AppTheme.violet,size:56))),const SizedBox(height:24),Text('Kenalan dulu, yuk!',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.w900)),const SizedBox(height:8),Text('Isi biodata singkat agar pengalaman kuismu lebih personal.',style:TextStyle(color:Theme.of(context).colorScheme.onSurfaceVariant,height:1.5)),const SizedBox(height:28),_field(_name,'Nama lengkap','Masukkan nama kamu',Icons.person_outline_rounded,validator:(v)=>v==null||v.trim().isEmpty?'Nama wajib diisi.':null),const SizedBox(height:16),_field(_nim,'NIM (opsional)','Masukkan NIM',Icons.badge_outlined),const SizedBox(height:16),_field(_program,'Program studi (opsional)','Contoh: Ilmu Komputer',Icons.school_outlined),const SizedBox(height:28),PrimaryButton(label:'Lanjut ke beranda',icon:Icons.arrow_forward_rounded,onPressed:_continue),const SizedBox(height:14),Center(child:Text('Biodata hanya digunakan untuk personalisasi tampilan kuis.',textAlign:TextAlign.center,style:TextStyle(fontSize:12,color:Theme.of(context).colorScheme.onSurfaceVariant)))])))))));}
Widget _field(TextEditingController c,String label,String hint,IconData icon,{String? Function(String?)? validator})=>TextFormField(controller:c,validator:validator,textCapitalization:TextCapitalization.words,decoration:InputDecoration(labelText:label,hintText:hint,prefixIcon:Icon(icon),filled:true,border:OutlineInputBorder(borderRadius:BorderRadius.circular(16),borderSide:BorderSide.none)));}
